// tests/uno-log.test.js
// The live terminal log is generated by game modules (logMove) and by the
// shared logger. These tests pin the readable UNO lines so a rule change does
// not silently turn the terminal back into a wall of card ids.
process.env.GAMENEST_LOG = '0';

const test = require('node:test');
const assert = require('node:assert');
const uno = require('../games/uno');
const gameLog = require('../games/lib/game-log');

function freshTable() {
  const state = uno.createState();
  uno.initGame(state, 2);
  state.hands[0] = [
    { color: 'red', value: '7', id: 'red-7-a' },
    { color: 'blue', value: '1', id: 'blue-1-a' },
  ];
  state.hands[1] = [
    { color: 'red', value: '3', id: 'red-3-a' },
    { color: 'blue', value: '5', id: 'blue-5-b' },
  ];
  state.discard = [{ color: 'red', value: '9', id: 'red-9-a' }];
  state.currentColor = 'red';
  state.currentPlayer = 0;
  state.direction = 1;
  state.winner = null;
  state.unoCalled = [true, true];
  state.unoWindow = null;
  state.unoResult = null;
  state.pendingDraw = null;
  state.lastAction = null;
  return state;
}

test('logMove describes a played card, its effect and the hand size', () => {
  const state = freshTable();
  assert.equal(uno.handleMove({ cardId: 'red-7-a' }, state, 0), null);
  const line = uno.logMove(state, { cardId: 'red-7-a' }, 0, { name: (i) => 'Hráč ' + (i + 1) });
  assert.match(line, /zahraje červená 7/);
  assert.match(line, /1 v ruce/);
});

test('logMove marks a 7 swap with the chosen player', () => {
  const state = freshTable();
  state.hands[0].push({ color: 'red', value: '2', id: 'red-2-a' });
  assert.equal(uno.handleMove({ cardId: 'red-7-a', swapTarget: 1 }, state, 0), null);
  const line = uno.logMove(state, { cardId: 'red-7-a', swapTarget: 1 }, 0, { name: (i) => 'Hráč ' + (i + 1) });
  assert.match(line, /výměna rukou s Hráč 2/);
});

test('logMove reports who lost the UNO shout race', () => {
  const state = freshTable();
  assert.equal(uno.handleMove({ cardId: 'red-7-a' }, state, 0), null);
  assert.ok(state.unoWindow, 'a one-card hand opens the shout window');
  assert.equal(uno.handleMove({ unoCall: true }, state, 1), null);
  const line = uno.logMove(state, { unoCall: true }, 1, { name: (i) => 'P' + (i + 1) });
  assert.match(line, /bere 2/);
  assert.equal(state.hands[0].length, 3, 'the forgetful player draws two');
});

test('logMove describes a draw and an ended turn', () => {
  const state = freshTable();
  state.hands[0] = [{ color: 'blue', value: '1', id: 'blue-1-a' }];
  state.unoCalled = [true, true];
  assert.equal(uno.handleMove({}, state, 0), null);
  const drawn = uno.logMove(state, {}, 0, { name: (i) => 'P' + (i + 1) });
  assert.match(drawn, /líže 1 kartu/);
  if (state.pendingDraw) {
    const ended = uno.logMove(state, { endTurn: true }, 0, { name: (i) => 'P' + (i + 1) });
    assert.match(ended, /nechá si líznutou kartu/);
  }
});

test('seatName resolves humans and bots; logging never throws', () => {
  const room = {
    game: 'uno',
    _roomId: 'ABCD',
    players: new Map([[{}, { index: 0, name: 'Tomáš' }]]),
    bots: new Map([[1, { name: 'AI 2' }]]),
  };
  assert.equal(gameLog.seatName(room, 0), 'Tomáš');
  assert.equal(gameLog.seatName(room, 1), 'AI 2');
  assert.equal(gameLog.seatName(room, 5), 'Sedadlo 6');
  assert.doesNotThrow(() => gameLog.logEvent(room, 'test'));
  assert.doesNotThrow(() => gameLog.logEvent(null, 'bez room'));
});
